"><template slot-scope="s">{{ s.row.siteStart }} 至 {{ s.row.siteEnd }}</template></el-table-column></template><el-table-column label="创建时间" width="130"><template slot-scope="s">{{ createTime(s.row) }}</template></el-table-column><el-table-column label="附件资料" width="120"><template slot-scope="s"><span>{{ attachmentText(s.row) }}</span></template></el-table-column><el-table-column label="操作" width="120" fixed="right"><template slot-scope="s"><el-button type="text" @click="openDialog('view',s.row)">查看</el-button><el-button type="text" @click="openDialog('edit',s.row)">编辑</el-button></template></el-table-column></el-table></el-card></div></main><el-dialog :title="dialogTitle" :visible.sync="dialogVisible" width="760px"><el-form :model="form" label-width="170px" :disabled="dialogMode==='view'"><div class="section-title">项目基本信息</div><el-form-item label="项目名称"><el-input v-model="form.project" /></el-form-item><template v-if="type==='safety'"><div class="section-title">安全“三同时”履行情况</div><el-form-item label="安全预评价编制单位"><el-input v-model="form.evaluationUnit" /></el-form-item><el-form-item label="安全预评价完成时间"><el-date-picker v-model="form.evaluationDate" type="date" value-format="yyyy-MM-dd" /></el-form-item><el-form-item label="安全设施设计专篇编制单位"><el-input v-model="form.designUnit" /></el-form-item><el-form-item label="安全设施设计专篇完成时间"><el-date-picker v-model="form.designDate" type="date" value-format="yyyy-MM-dd" /></el-form-item><el-form-item label="安全验收报告编制单位"><el-input v-model="form.acceptanceUnit" /></el-form-item><el-form-item label="安全验收报告完成时间"><el-date-picker v-model="form.acceptanceDate" type="date" value-format="yyyy-MM-dd" /></el-form-item><el-form-item label="应急预案有效期限"><el-date-picker v-model="emergencyRange" type="daterange" value-format="yyyy-MM-dd" range-separator="至" /></el-form-item><el-form-item label="安全评价有效期限"><el-date-picker v-model="safetyRange" type="daterange" value-format="yyyy-MM-dd" range-separator="至" /></el-form-item><el-form-item label="危险化学品经营许可证有效期限"><el-date-picker v-model="hazardousRange" type="daterange" value-format="yyyy-MM-dd" range-separator="至" /></el-form-item></template><template v-else><div class="section-title">职业健康“三同时”履行情况</div><el-form-item label="职业病危害预评价编制单位"><el-input v-model="form.preUnit" /></el-form-item><el-form-item label="职业病危害预评价完成时间"><el-date-picker v-model="form.preDate" type="date" value-format="yyyy-MM-dd" /></el-form-item><el-form-item label="职业病防护设施设计专篇编制单位"><el-input v-model="form.designUnit" /></el-form-item><el-form-item label="职业病防护设施设计专篇完成时间"><el-date-picker v-model="form.designDate" type="date" value-format="yyyy-MM-dd" /></el-form-item><el-form-item label="职业病危害控制效果评价编制单位"><el-input v-model="form.controlUnit" /></el-form-item><el-form-item label="控制效果评价完成时间"><el-date-picker v-model="form.controlDate" type="date" value-format="yyyy-MM-dd" /></el-form-item><el-form-item label="备案时间"><el-date-picker v-model="form.filingDate" type="date" value-format="yyyy-MM-dd" /></el-form-item><el-form-item label="场所检测有效期限"><el-date-picker v-model="siteRange" type="daterange" value-format="yyyy-MM-dd" range-separator="至" /></el-form-item></template><el-form-item label="附件资料"><el-upload action="#" :auto-upload="false" :disabled="dialogMode==='view'"><el-button icon="el-icon-upload2">上传附件</el-button></el-upload></el-form-item></el-form><span slot="footer"><el-button @click="dialogVisible=false">取消</el-button><el-button v-if="dialogMode!=='view'" type="primary" @click="save">保存</el-button></span></el-dialog></div></div>
</template>
<script>
import { safetyProjects, healthProjects } from '../mock/safetyHealth'
export default { name: 'ThreeSameSpecialList', props: { type: String }, data () { return { keyword: '', createRange: [], rows: this.type === 'safety' ? safetyProjects : healthProjects, dialogVisible: false, dialogMode: 'view', form: {}, emergencyRange: [], safetyRange: [], hazardousRange: [], siteRange: [] } }, computed: { filteredRows () { return this.rows.filter(x => (!this.keyword || x.project.indexOf(this.keyword) > -1) && this.inCreateRange(x)) }, dialogTitle () { return this.dialogMode === 'view' ? '查看' + (this.type === 'safety' ? '安全' : '职业健康') + '三同时项目' : this.dialogMode === 'edit' ? '编辑' + (this.type === 'safety' ? '安全' : '职业健康') + '三同时项目' : '新增' + (this.type === 'safety' ? '安全' : '职业健康') + '三同时项目' } }, methods: { createTime (row) { return ({ 1: '2026-01-08', 2: '2026-01-08', 3: '2026-01-09', 4: '2026-01-09' }[row.id] || '-') }, inCreateRange (row) { if (!this.createRange || this.createRange.length !== 2) return true; const value = this.createTime(row); return value >= this.createRange[0] && value <= this.createRange[1] }, selectCategory (name) { this.$router.push('/three-same/' + name) }, switchType (tab) { if (tab.name === 'environment') this.$router.push('/three-same/environment'); else if (tab.name !== this.type) this.$router.push('/three-same/' + tab.name) }, openDialog (mode, row) { this.dialogMode = mode; this.form = Object.assign({}, row || {}); this.dialogVisible = true }, attachmentText (row) { return row.attachments && row.attachments.length ? row.attachments.length + '个文件' : '暂无附件' }, save () { this.dialogVisible = false; this.$message.success('已保存到本地 Mock 数据') } } }
</script>
